<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Text Reverser','description'=>'Reverse text instantly while preserving every character.','url'=>'https://smarttoolz.in/tools/text-reverser/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Text Reverser</h1><p>Reverse text instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><textarea id="i" rows="10" placeholder="Enter text..."></textarea><button id="go" class="tool-btn">Reverse Text</button><textarea id="o" rows="10" readonly></textarea></div></section></main><script>go.onclick=()=>o.value=[...i.value].reverse().join('')</script><?php smarttoolz_tool_page_end(); ?>